/* Pure, local-first route and learning rules. */
const ACADEMY_MIN_AGE=13;
function academyNormalize(s){return String(s??'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’]/g,"'").replace(/\s+/g,' ')}
function academyGrade(q,value){if(q.type==='mcq')return Number.isInteger(value)&&value===q.answer;if(q.type==='numeric'){const n=Number(String(value).replace(',','.'));return String(value).trim()!==''&&Number.isFinite(n)&&Math.abs(n-q.answer)<=(q.tolerance??.00001)}if(['short','fill'].includes(q.type))return [q.answer,...(q.accepted||[])].filter(x=>typeof x==='string').some(x=>academyNormalize(x)===academyNormalize(value));return false}
function academySteps(path){return path.stages.flatMap((s,stageIndex)=>s.steps.map(x=>({...x,stageId:s.id,stageIndex})))}
function academyNext(path,progress){return academySteps(path).find(s=>!progress[s.id]?.complete)||null}
function academyUnlocked(path,id,progress){const rows=academySteps(path),i=rows.findIndex(x=>x.id===id);return i===0||i>0&&!!progress[rows[i-1].id]?.complete||!!progress[id]?.complete}
function academyFeatureEnabled(kind,features){const flag={etranger:'showAbroad',opportunites:'showOpportunities',portfolio:'showPortfolio'}[kind];return !flag||features?.[flag]===true}
function academyDomainComingSoon(domainId,features){return features?.otherDomainsComingSoon===true&&domainId!=='tech'}
function academyRoute(hash){let decoded;try{decoded=decodeURI(String(hash||'#/accueil'))}catch{decoded='#/accueil'}const b=decoded.replace(/^#\/?/,'').split('/').filter(Boolean),aliases={home:'accueil',cours:'bibliotheque',metiers:'avenir',progres:'progression'};if(b[0]==='cours'&&b[1])return {kind:'path',id:'cours-'+b[1],nav:'mes-cours',canonical:'#/parcours/cours-'+b[1]};const first=aliases[b[0]]||b[0]||'accueil';if(first==='avenir'&&b[1]==='formation')return {kind:b[3]!==undefined?'step':'path',id:'cours-'+b[2],stepId:b[3],nav:'avenir',canonical:'#/'+b.join('/')};if(first==='apprendre')return {kind:'apprendre',id:b[1],careerId:b[2],stepId:b[3],nav:'apprendre',canonical:'#/'+b.join('/')};if(first==='mes-cours'&&b.length>=4)return {kind:b[4]!==undefined?'step':'path',id:'cours-'+b[3],stepId:b[4],nav:'mes-cours',canonical:'#/'+b.join('/')};if(first==='parcours')return {kind:b[2]==='etape'?'step':'path',id:b[1],stepId:b[3],nav:b[1]?.startsWith('cours-')?'mes-cours':'avenir',canonical:'#/'+b.join('/')};return {kind:first,id:b[1],careerId:b[2],nav:['ressource','sources','collection'].includes(first)?'bibliotheque':['etranger','opportunites'].includes(first)?'avenir':first,canonical:'#/'+[first,...b.slice(1)].join('/')}}
function academySafeState(raw){const x=raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{};const clean={onboarded:x.onboarded===true,revisionDate:typeof x.revisionDate==='string'?x.revisionDate.slice(0,10):'',progress:{},answers:{},practice:{},notes:{},projects:{},bundles:[],weekly:{},checklists:{},cv:{},savedOpps:[],interest:{},activePath:typeof x.activePath==='string'?x.activePath.slice(0,80):null};for(const k of ['progress','answers','practice','notes','projects','weekly','checklists','cv','interest'])if(x[k]&&typeof x[k]==='object'&&!Array.isArray(x[k])){for(const [id,v]of Object.entries(x[k]).slice(0,1500)){if(!/^[\w:-]{1,160}$/.test(id)||['__proto__','constructor','prototype'].includes(id))continue;if(k==='practice')clean[k][id]=Number.isInteger(v)?Math.max(0,Math.min(99,v)):0;else if(k==='notes'||k==='projects'||k==='cv')clean[k][id]=typeof v==='string'?v.slice(0,6000):'';else if(k==='weekly')clean[k][id]=Math.max(.5,Math.min(20,Number(v)||3));else if(k==='progress')clean[k][id]={complete:v?.complete===true,at:typeof v?.at==='string'?v.at.slice(0,40):''};else if(k==='answers')clean[k][id]={value:typeof v?.value==='number'?v.value:String(v?.value??'').slice(0,2000),correct:v?.correct===true,checked:v?.checked===true,hints:Math.min(3,Math.max(0,Number(v?.hints)||0))};else if(k==='interest')clean[k][id]=v===true;else if(k==='checklists'&&v&&typeof v==='object'){const record={};for(const [field,value]of Object.entries(v).slice(0,30)){if(!/^[a-z0-9-]{1,80}$/.test(field)||['constructor','prototype'].includes(field))continue;record[field]=field==='date'?String(value).slice(0,10):value===true}clean[k][id]=record}}}for(const k of ['bundles','savedOpps'])if(Array.isArray(x[k]))clean[k]=x[k].filter(v=>typeof v==='string'&&/^[\w-]{1,80}$/.test(v)).slice(0,100);return clean}
function academyIcs(item){if(!item.deadline)return null;const clean=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'),date=new Date(item.deadline);if(!Number.isFinite(+date))return null;return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Nunya//Calendrier//FR','BEGIN:VEVENT','UID:'+item.id+'@nunya.local','DTSTAMP:20261101T000000Z','DTSTART:'+date.toISOString().replace(/[-:]/g,'').replace('.000',''),'SUMMARY:'+clean(item.title),'DESCRIPTION:'+clean(item.eligibility),'URL:'+item.link,'END:VEVENT','END:VCALENDAR'].join('\r\n')+'\r\n'}

function academySearchDistance(a,b){const d=Array.from({length:a.length+1},(_,i)=>[i]);for(let j=0;j<=b.length;j++)d[0][j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]!==b[j-1]));return d[a.length][b.length]}
function academyCurriculumSearchScore(row,terms){const title=academyNormalize(row.title),titleWords=title.match(/[a-z0-9]+/g)||[],tagWords=academyNormalize(row.terms).match(/[a-z0-9]+/g)||[];let score=0;for(const raw of terms){const t=academyNormalize(raw);if(!t)continue;const directTitle=titleWords.includes(t),directTag=tagWords.includes(t);if(directTitle)score=Math.max(score,100);else if(directTag)score=Math.max(score,80);else if(t.length>=4&&titleWords.some(w=>w.startsWith(t)))score=Math.max(score,70);else if(t.length>=4&&tagWords.some(w=>w.startsWith(t)))score=Math.max(score,60);else if(row.kind!=='Ressources'&&t.length>=4&&[...titleWords,...tagWords].some(w=>w.length>=4&&academySearchDistance(w.replace(/s$/,''),t.replace(/s$/,''))<=1))score=Math.max(score,40)}return score}

// Navigation is within the current lesson until every question was checked correctly.
function academyPracticeProgress(step,namespace,answers,savedIndex){const questions=step.practice||[],passed=questions.map(q=>{const a=answers[namespace+'-'+q.id];return a?.checked===true&&a.correct===true}),firstPending=passed.indexOf(false),saved=Number.isInteger(savedIndex)&&savedIndex>=0&&savedIndex<questions.length,index=saved?savedIndex:Math.max(0,firstPending);return {index,total:questions.length,completed:passed.filter(Boolean).length,complete:firstPending<0,currentPassed:passed[index]===true,nextIndex:passed.findIndex((ok,i)=>!ok&&i>index)>=0?passed.findIndex((ok,i)=>!ok&&i>index):firstPending}}
